from sys import stdin, stdout
import math

MOD = 998244353

def count_good_permutations(n, pairs):
    def factorial(x):
        return math.factorial(x) % MOD

    def inverse_factorial(x):
        return pow(factorial(x), MOD - 2, MOD)

    def choose(n, k):
        return (factorial(n) * inverse_factorial(k) * inverse_factorial(n - k)) % MOD

    # Count the number of ways to partition the pairs into two groups
    # such that neither group forms a sorted sequence by either element
    def count_partitions(pairs):
        def is_sorted_by_first(group):
            return all(a <= b for a, b in zip(*group))

        def is_sorted_by_second(group):
            return all(b <= c for _, b, _, c in zip(*group))

        def dfs(index, first_group, second_group):
            if index == len(pairs):
                if not is_sorted_by_first(first_group) and not is_sorted_by_second(second_group):
                    return 1
                return 0

            count = 0
            count += dfs(index + 1, first_group + [pairs[index]], second_group)
            count += dfs(index + 1, first_group, second_group + [pairs[index]])
            return count

        return dfs(0, [], [])

    total_permutations = factorial(n)
    bad_partitions = count_partitions(pairs)
    good_partitions = total_permutations - bad_partitions

    return good_partitions

