        mid = len(arr) // 2
        left = merge_sort(arr[:mid])
        right = merge_sort(arr[mid:])
        return merge(left, right)

    def merge(left, right):
        merged = []
        i = j = 0
        while i < len(left) and j < len(right):
            if left[i] < right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                j += 1
        merged.extend(left[i:])
        merged.extend(right[j:])
        return merged

    def get_count(pairs):
        sorted_by_first = merge_sort([(pair[0], i) for i, pair in enumerate(pairs)])
        sorted_by_second = merge_sort([(pair[1], i) for i, pair in enumerate(pairs)])

        count = 0
        for i in range(n):
