                    inversions += 1
                pos[x] -= 1
        return inversions

    def mod_inv(a, m=MOD):
        return pow(a, m-2, m)

    def comb(n, k):
        return factorial(n) * mod_inv(factorial(k)) % MOD * mod_inv(factorial(n-k)) % MOD

    # Separate the sequence into two lists based on the sorting of the first and second elements
    first_sorted = []
    second_sorted = []
    first_unsorted = []
    second_unsorted = []

    for a, b in seq:
        if a < b:
            first_sorted.append((a, b))
        elif a > b:
            first_unsorted.append((a, b))
        elif a == b:
            first_sorted.append((a, b))
        if b < a:
            second_sorted.append((a, b))
        elif b > a:
            second_unsorted.append((a, b))
        elif b == a:
            second_sorted.append((a, b))

    # Calculate the number of ways to sort each list
    first_sorted_count = len(first_sorted)
    first_unsorted_count = len(first_unsorted)
    second_sorted_count = len(second_sorted)
    second_unsorted_count = len(second_unsorted)

